-- =====================================================================
-- RUSH CASE — пересборка дропа 27.11.2026 (владелец): BLAST (cs2), MAJOR, «В гостях у бабушки» (6 кейсов), «Кейсы карт» (6 кейсов).
-- Интересные скины, разное число позиций, самый дешёвый скин ≈ половина цены кейса, окупаемость — та же, что была:
--   BLAST 83,35%, MAJOR 83,94%, Попрошайка 84,93%, ЖАБ ЖАБЫЧ 85,05%, ГРЯДКА 84,96%, Баба Боря 81,18%, ВНУКА ВНУК 84,95%,
--   Деда Дед 84,99%, MIRAGE 80%, NUKE / TRAIN / ANCIENT / CACHE / Cobblestone 78%.
-- Раньше часть окупаемости давала «удача кейса» (case_settings.luck: BLAST ×3, MAJOR ×1,45, бабушкины ×1,06–1,2) — теперь она
-- уже внутри шансов, поэтому удача этих кейсов = 1 (в админке ползунки покажут ×1). Составы — в js/app.js (CASES, PITY_SETS),
-- здесь те же составы сразу кладутся на сервер (cases_srv), чтобы не ждать admSync; admSync потом зальёт то же самое.
-- Старые значения (удача, составы cases_srv, составы и описания custom_cases) — в site_cfg 'bak:drop:20261127'.
-- Запуск: Supabase → SQL Editor → вставить весь файл → Run. Повторный запуск безопасен.
-- =====================================================================

-- 1) копия старого
insert into public.site_cfg (k, v, updated_at)
  select 'bak:drop:20261127', jsonb_build_object(
    'luck', (select coalesce(jsonb_object_agg(id, luck), '{}'::jsonb) from public.case_settings where id in ('cs2', 'major', 'mirage', 'poproshayka', 'zhaba', '1133444', 'bababorya', 'tnir', 'dedaded', '111111', '113322', 'antient', 'cache', 'cobblestone')),
    'srv', (select coalesce(jsonb_object_agg(id, items), '{}'::jsonb) from public.cases_srv where id in ('cs2', 'major', 'mirage', 'poproshayka', 'zhaba', '1133444', 'bababorya', 'tnir', 'dedaded', '111111', '113322', 'antient', 'cache', 'cobblestone')),
    'custom', (select coalesce(jsonb_object_agg(id, jsonb_build_object('items', items, 'sub', sub)), '{}'::jsonb) from public.custom_cases where id in ('111111', '113322', '1133444', 'poproshayka', 'zhaba', 'bababorya', 'tnir', 'dedaded', 'antient', 'cache', 'cobblestone'))
  ), now()
  on conflict (k) do nothing;

-- 2) удача этих кейсов ×1 (окупаемость уже в шансах)
insert into public.case_settings (id, luck, updated_at) values
  ('cs2', 1, now()),
  ('major', 1, now()),
  ('mirage', 1, now()),
  ('poproshayka', 1, now()),
  ('zhaba', 1, now()),
  ('1133444', 1, now()),
  ('bababorya', 1, now()),
  ('tnir', 1, now()),
  ('dedaded', 1, now()),
  ('111111', 1, now()),
  ('113322', 1, now()),
  ('antient', 1, now()),
  ('cache', 1, now()),
  ('cobblestone', 1, now())
on conflict (id) do update set luck = 1, updated_at = now();

