-- 5) описания кейсов из админки
update public.custom_cases set sub = v.sub, updated_at = now() from (values
  ('111111', $s$Коллекции Nuke и радиация: M4A1-S Control Panel, Glock-18 Ядерный сад, M4A4 Radiation Hazard, AWP Containment Breach и ещё 26 — от 73 ₽, каждое ~7-е открытие дороже кейса. Джекпоты — M4A4 X-Ray, AK-47 и Glock-18 Wasteland Rebel, Skeleton Knife Ultraviolet, Butterfly Knife Urban Masked.$s$),
  ('113322', $s$Коллекции Train — сталь, рельсы и медь: M4A4 Griffin, Desert Eagle Light Rail, USP-S Whiteout, AWP LongDog и ещё 28 — от 80 ₽, каждое ~9-е открытие дороже кейса. Джекпоты — Glock-18 Gamma Doppler, M4A4 Hellfire и The Coalition, Classic Knife Slaughter, Butterfly Knife Blue Steel.$s$),
  ('1133444', $s$С бабушкиной грядки — цветы, ягоды и дерево: USP-S Black Lotus, Desert Eagle Mulberry, M4A4 Spider Lily, Glock-18 Ядерный сад и ещё 27 — от 37 ₽, каждое ~9-е открытие дороже кейса. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» или нож/перчатки. Джекпоты — M4A4 В живом цвете, Hand Wraps Arboreal, Skeleton Knife.$s$),
  ('poproshayka', $s$Скины бедняка, но с характером: Glock-18 Кролик в тени, M4A4 Etch Lord, USP-S Ticket to Hell, AK-47 Slate и ещё 20 — от 20 ₽. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» (красный AK-47).$s$),
  ('zhaba', $s$Болотный дроп: M4A1-S Emphorosaur-S, Galil AR Galigator, AWP Гадюка, M4A1-S Basilisk и ещё 28 — от 26 ₽, каждое ~9-е открытие дороже кейса. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» или перчатки. Джекпоты — AK-47 Аквамариновая месть, AWP Скоростной зверь, перчатки Snakebite.$s$),
  ('bababorya', $s$Бабушка, коты и варенье: AWP ЛАПКИ, MAC-10 Cat Fight, USP-S Sleeping Potion, AWP Fever Dream и ещё 25 — от 46 ₽, каждое ~14-е открытие дороже кейса. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» или перчатки. Джекпоты — Glock-18 Королева пуль, перчатки Queen Jaguar и Chocolate Chesterfield.$s$),
  ('tnir', $s$Скины внука-геймера — неон, глитч и принтстрим: USP-S Ticket to Hell, M4A1-S Glitched Paint, Glock-18 Vogue, USP-S Cortex и ещё 37 — от 60 ₽, каждое ~11-е открытие дороже кейса. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» или нож. Джекпоты — USP-S Printstream, AWP и Glock-18 Неонуар, M4A1-S Player Two, Skeleton Knife Ultraviolet.$s$),
  ('dedaded', $s$Дедов арсенал — камуфляж, бронза и ржавчина: Desert Eagle Bronze Deco, AK-47 Uncharted, USP-S Guardian, AK-47 Slate и ещё 35 — от 61 ₽, каждое ~11-е открытие дороже кейса. Гарант: 75-е открытие подряд — шанс на «Засекреченное», 150-е — точно «Засекреченное» или нож. Джекпоты — M4A4 Desert-Strike, AK-47 Inheritance, FAMAS Commemoration, Bayonet Rust Coat.$s$),
  ('antient', $s$Коллекция Ancient — джунгли, тигры и ацтеки: USP-S Blood Tiger, MAC-10 Curse, P90 Tiger Pit, USP-S Ancient Visions и ещё 27 — от 71 ₽, каждое ~7-е открытие дороже кейса. Джекпоты — AK-47 Ягуар и Panthera onca, Flip Knife Lore, M4A1-S Добро пожаловать в джунгли, Butterfly Knife Зуб тигра.$s$),
  ('cache', $s$Коллекция Cache — химия и ядерный сад: FAMAS Styx, Glock-18 Реактор, Tec-9 Токсичность, Galil AR Cerberus и ещё 26 — от 152 ₽, каждое ~9-е открытие дороже кейса. Джекпоты — AK-47 Fuel Injector и Hydroponic, M9 Bayonet Bright Water, Karambit Autotronic.$s$),
  ('cobblestone', $s$Коллекция Cobblestone — рыцари и драконы: Glock-18 Royal Legion, M4A4 Dragon King, Desert Eagle Kumicho Dragon, M4A1-S Guardian и ещё 25 — от 183 ₽, каждое ~6-е открытие дороже кейса. Джекпоты — CZ75-Auto Chalice, M9 Bayonet Black Laminate, Butterfly Knife Lore, M4A1-S Knight, AWP Dragon Lore.$s$)
) v(id, sub) where custom_cases.id = v.id;

-- проверка: у всех 14 кейсов удача 1 и новый состав
select s.id, s.price, jsonb_array_length(s.items) as skins, cs.luck, s.updated_at
  from public.cases_srv s left join public.case_settings cs on cs.id = s.id
  where s.id in ('cs2', 'major', 'mirage', 'poproshayka', 'zhaba', '1133444', 'bababorya', 'tnir', 'dedaded', '111111', '113322', 'antient', 'cache', 'cobblestone') order by s.price, s.id;
